/// GML: `oVampire/collision_oBlood#0`.
pub fn collision_oBlood_a0(g: &mut World, cx: &mut Ctx) -> R<()> {
    let cx = &mut cx.clone();
    // 1: hp += 1;
    g.at("oVampire/collision_oBlood#0", 1);
    g.set(cx.this, v::hp, lenient(Value::add, g.get(cx.this, v::hp)?, &r(1.0))?)?;
    // 2: with (other)
    g.at("oVampire/collision_oBlood#0", 2);
    {
        let t = r(-2.0);
        let mut it1 = g.with_iter(cx, &t)?;
        let outer3 = (cx.this, cx.other);
        'with1: while let Some(h2) = it1.next(g) {
            (cx.this, cx.other) = (h2, outer3.0);
            // 2: instance_destroy();
            g.at("oVampire/collision_oBlood#0", 2);
            b::instance_destroy(g, cx, [])?;
        }
        (cx.this, cx.other) = outer3;
    }
    Ok(())
}

/// GML: `oVampire/collision_oCharacter#0`.
pub fn collision_oCharacter_a0(g: &mut World, cx: &mut Ctx) -> R<()> {
    // 1: if (abs(other.x - (x + 8)) > 8)
    g.at("oVampire/collision_oCharacter#0", 1);
    if ({ let a = [g.get(cx.other, v::x)?.sub(&g.get(cx.this, v::x)?.add(&r(8.0))?)?]; b::abs(g, cx, a)? }).gml_gt(&r(8.0))? {
    } else {
        // 5: if (!other.dead && (other.state == 15 || other.state == 16) && other.y < y + 5 && !other.swimming)
        g.at("oVampire/collision_oCharacter#0", 5);
        if and(and(and(g.get(cx.other, v::dead)?.not()?.is_truthy(), or(g.get(cx.other, v::state)?.gml_eq(&r(15.0))?, g.get(cx.other, v::state)?.gml_eq(&r(16.0))?)), g.get(cx.other, v::y)?.gml_lt(&g.get(cx.this, v::y)?.add(&r(5.0))?)?), g.get(cx.other, v::swimming)?.not()?.is_truthy()) {
            // 8: if (status < STUNNED)
            g.at("oVampire/collision_oCharacter#0", 8);
            if g.get(cx.this, v::status)?.gml_lt(&g.get(cx.this, v::STUNNED)?)? {
                // 10: other.yVel = -6 - 0.2 * other.yVel;
                g.at("oVampire/collision_oCharacter#0", 10);
                g.set(cx.other, v::yVel, r(-6.0).sub(&r(0.2).mul(&g.get(cx.other, v::yVel)?)?)?)?;
                // 11: if (global.hasSpikeShoes)
                g.at("oVampire/collision_oCharacter#0", 11);
                if g.gget(gv::hasSpikeShoes)?.is_truthy() {
                    // 11: hp -= 3 * (floor(other.fallTimer / 16) + 1);
                    g.at("oVampire/collision_oCharacter#0", 11);
                    {
                        let old = g.get(cx.this, v::hp)?;
                        let x = lenient(Value::sub, old, &r(3.0).mul(&({ let a = [g.get(cx.other, v::fallTimer)?.div(&r(16.0))?]; b::floor(g, cx, a)? }).add(&r(1.0))?)?)?;
                        g.set(cx.this, v::hp, x)?;
                    }
                    // 11: if (!bloodless)
                    g.at("oVampire/collision_oCharacter#0", 11);
                    if g.get(cx.this, v::bloodless)?.not()?.is_truthy() {
                        // 11: instance_create(other.x, other.y + 8, oBlood);
                        g.at("oVampire/collision_oCharacter#0", 11);
                        { let a = [g.get(cx.other, v::x)?, g.get(cx.other, v::y)?.add(&r(8.0))?, obj::oBlood]; b::instance_create(g, cx, a)? };
                    }
                } else {
                    // 12: hp -= 1 * (floor(other.fallTimer / 16) + 1);
                    g.at("oVampire/collision_oCharacter#0", 12);
                    {
                        let old = g.get(cx.this, v::hp)?;
                        let x = lenient(Value::sub, old, &r(1.0).mul(&({ let a = [g.get(cx.other, v::fallTimer)?.div(&r(16.0))?]; b::floor(g, cx, a)? }).add(&r(1.0))?)?)?;
                        g.set(cx.this, v::hp, x)?;
                    }
                }
                // 13: other.fallTimer = 0;
                g.at("oVampire/collision_oCharacter#0", 13);
                g.set(cx.other, v::fallTimer, r(0.0))?;
                // 14: countsAsKill = true;
                g.at("oVampire/collision_oCharacter#0", 14);
                g.set(cx.this, v::countsAsKill, r(1.0))?;
                // 15: status = STUNNED;
                g.at("oVampire/collision_oCharacter#0", 15);
                g.set(cx.this, v::status, g.get(cx.this, v::STUNNED)?)?;
                // 16: counter = stunTime;
                g.at("oVampire/collision_oCharacter#0", 16);
                g.set(cx.this, v::counter, g.get(cx.this, v::stunTime)?)?;
                // 17: yVel = -6;
                g.at("oVampire/collision_oCharacter#0", 17);
                g.set(cx.this, v::yVel, r(-6.0))?;
                // 18: if (other.x < x + 8)
                g.at("oVampire/collision_oCharacter#0", 18);
                if g.get(cx.other, v::x)?.gml_lt(&g.get(cx.this, v::x)?.add(&r(8.0))?)? {
                    // 18: xVel += 1;
                    g.at("oVampire/collision_oCharacter#0", 18);
                    g.set(cx.this, v::xVel, lenient(Value::add, g.get(cx.this, v::xVel)?, &r(1.0))?)?;
                } else {
                    // 19: xVel -= 1;
                    g.at("oVampire/collision_oCharacter#0", 19);
                    g.set(cx.this, v::xVel, lenient(Value::sub, g.get(cx.this, v::xVel)?, &r(1.0))?)?;
                }
                // 20: image_speed = 0.5;
                g.at("oVampire/collision_oCharacter#0", 20);
                g.set(cx.this, v::image_speed, r(0.5))?;
                // 21: playSound(global.sndHit);
                g.at("oVampire/collision_oCharacter#0", 21);
                { let a = [g.gget(gv::sndHit)?]; scr::playSound(g, cx, &a)? };
            }
        } else {
            // 24: if (other.invincible == 0)
            g.at("oVampire/collision_oCharacter#0", 24);
            if g.get(cx.other, v::invincible)?.gml_eq(&r(0.0))? {
                // 26: if (status < STUNNED)
                g.at("oVampire/collision_oCharacter#0", 26);
                if g.get(cx.this, v::status)?.gml_lt(&g.get(cx.this, v::STUNNED)?)? {
                    // 28: other.blink = 30;
                    g.at("oVampire/collision_oCharacter#0", 28);
                    g.set(cx.other, v::blink, r(30.0))?;
                    // 29: other.invincible = 30;
                    g.at("oVampire/collision_oCharacter#0", 29);
                    g.set(cx.other, v::invincible, r(30.0))?;
                    // 30: if (other.y < y)
                    g.at("oVampire/collision_oCharacter#0", 30);
                    if g.get(cx.other, v::y)?.gml_lt(&g.get(cx.this, v::y)?)? {
                        // 31: other.yVel = -6;
                        g.at("oVampire/collision_oCharacter#0", 31);
                        g.set(cx.other, v::yVel, r(-6.0))?;
                    }
                    // 32: if (other.x < x)
                    g.at("oVampire/collision_oCharacter#0", 32);
                    if g.get(cx.other, v::x)?.gml_lt(&g.get(cx.this, v::x)?)? {
                        // 33: other.xVel = -6;
                        g.at("oVampire/collision_oCharacter#0", 33);
                        g.set(cx.other, v::xVel, r(-6.0))?;
                    } else {
                        // 35: other.xVel = 6;
                        g.at("oVampire/collision_oCharacter#0", 35);
                        g.set(cx.other, v::xVel, r(6.0))?;
                    }
                    // 36: instance_create(other.x, other.y, oBlood);
                    g.at("oVampire/collision_oCharacter#0", 36);
                    { let a = [g.get(cx.other, v::x)?, g.get(cx.other, v::y)?, obj::oBlood]; b::instance_create(g, cx, a)? };
                    // 38: if (global.plife > 0)
                    g.at("oVampire/collision_oCharacter#0", 38);
                    if g.gget(gv::plife)?.gml_gt(&r(0.0))? {
                        // 38: global.plife -= 1;
                        g.at("oVampire/collision_oCharacter#0", 38);
                        g.gset(gv::plife, lenient(Value::sub, g.gget(gv::plife)?, &r(1.0))?)?;
                    }
                    // 39: playSound(global.sndHurt);
                    g.at("oVampire/collision_oCharacter#0", 39);
                    { let a = [g.gget(gv::sndHurt)?]; scr::playSound(g, cx, &a)? };
                }
            }
        }
    }
    Ok(())
}

